import json
import os
import sys
import base64
import hashlib
from collections import defaultdict

def issue_token(client_id, expiry):
    secret = os.getenv('QUOTA_SECRET')
    if not secret:
        raise ValueError("QUOTA_SECRET environment variable not set")
    data = f"{client_id}{expiry}".encode()
    token = base64.urlsafe_b64encode(hashlib.sha256(data).digest()).decode().rstrip('=')
    return token

def decode_token(token):
    try:
        decoded = base64.urlsafe_b64decode(token + '=' * (4 - len(token) % 4))
        hash_obj = hashlib.sha256(decoded)
        return hash_obj.digest()
    except:
        return None

def check_requests():
    limits = {}
    try:
        with open('limits.json', 'r') as f:
            limits = json.load(f)
    except FileNotFoundError:
        pass

    window_counts = defaultdict(int)
    current_window = None

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            data = json.loads(line)
            client_id = data['client_id']
            token = data['token']
            timestamp = data['timestamp']

            if client_id not in limits:
                print("DENY")
                continue

            decoded_hash = decode_token(token)
            if not decoded_hash:
                print("DENY")
                continue

            secret = os.getenv('QUOTA_SECRET')
            if not secret:
                print("DENY")
                continue

            data_to_hash = f"{client_id}{timestamp}".encode()
            expected_hash = hashlib.sha256(data_to_hash).digest()
            if decoded_hash != expected_hash:
                print("DENY")
                continue

            window = timestamp // 60
            if window != current_window:
                window_counts = defaultdict(int)
                current_window = window

            if window_counts[client_id] >= limits[client_id]:
                print("DENY")
            else:
                window_counts[client_id] += 1
                print("ALLOW")
        except (json.JSONDecodeError, KeyError):
            print("DENY")

if __name__ == "__main__":
    if len(sys.argv) != 4 or sys.argv[1] != "issue":
        print("Usage: python quota_tokens.py issue <client_id> <expiry>")
        sys.exit(1)

    client_id = sys.argv[2]
    expiry = int(sys.argv[3])
    print(issue_token(client_id, expiry))

    elif len(sys.argv) != 2 or sys.argv[1] != "check":
        print("Usage: python quota_tokens.py check")
        sys.exit(1)

    check_requests()

import argparse
import json
import os
import sys
from datetime import datetime
from hashlib import sha256
from typing import Dict, List, Optional

class QuotaManager:
    def __init__(self):
        self.limits: Dict[str, int] = {}
        self.window_counts: Dict[str, Dict[int, int]] = {}

    def load_limits(self, filename: str) -> None:
        with open(filename, 'r') as f:
            self.limits = json.load(f)

    def generate_token(self, client_id: str, expiry: int) -> str:
        secret = os.getenv('QUOTA_SECRET')
        if not secret:
            raise ValueError("QUOTA_SECRET environment variable not set")
        data = f"{client_id}{expiry}{secret}".encode()
        return sha256(data).hexdigest()

    def check_token(self, token: str, client_id: str, timestamp: int) -> bool:
        secret = os.getenv('QUOTA_SECRET')
        if not secret:
            raise ValueError("QUOTA_SECRET environment variable not set")

        # Reconstruct client_id and expiry from token
        data = f"{token[:32]}{token[32:64]}".encode()
        reconstructed_secret = sha256(data).hexdigest()
        if reconstructed_secret != secret:
            return False

        # Extract client_id and expiry from token
        try:
            client_id_from_token = token[:32]
            expiry_from_token = int(token[32:64])
        except:
            return False

        if client_id_from_token != client_id:
            return False

        if expiry_from_token <= timestamp:
            return False

        return True

    def check_request(self, request: Dict[str, str | int]) -> str:
        client_id = request['client_id']
        token = request['token']
        timestamp = request['timestamp']

        if client_id not in self.limits:
            return 'DENY'

        window = timestamp // 60
        if client_id not in self.window_counts:
            self.window_counts[client_id] = {}

        if window not in self.window_counts[client_id]:
            self.window_counts[client_id][window] = 0

        if self.check_token(token, client_id, timestamp):
            if self.window_counts[client_id][window] < self.limits[client_id]:
                self.window_counts[client_id][window] += 1
                return 'ALLOW'
            else:
                return 'DENY'
        else:
            return 'DENY'

def main():
    manager = QuotaManager()
    parser = argparse.ArgumentParser()
    subparsers = parser.add_subparsers(dest='command', required=True)

    # Issue command
    issue_parser = subparsers.add_parser('issue')
    issue_parser.add_argument('client_id', type=str)
    issue_parser.add_argument('expiry', type=int)

    # Check command
    check_parser = subparsers.add_parser('check')
    check_parser.add_argument('--limits', type=str, default='limits.json')

    args = parser.parse_args()

    if args.command == 'issue':
        token = manager.generate_token(args.client_id, args.expiry)
        print(token)
    elif args.command == 'check':
        manager.load_limits(args.limits)
        for line in sys.stdin:
            try:
                request = json.loads(line.strip())
                print(manager.check_request(request))
            except json.JSONDecodeError:
                continue

if __name__ == '__main__':
    main()

import json
import os
import sys
import hashlib
import time
from collections import defaultdict

QUOTA_SECRET = os.getenv('QUOTA_SECRET')

def issue():
    client_id = sys.argv[1]
    expiry = int(sys.argv[2])
    secret = QUOTA_SECRET
    if not secret:
        sys.exit(1)
    data = f"{client_id}{expiry}".encode()
    token = hashlib.sha256(data + secret.encode()).hexdigest()
    print(token)

def check():
    limits = {}
    try:
        with open('limits.json') as f:
            limits = json.load(f)
    except:
        pass

    window_counts = defaultdict(int)
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        data = json.loads(line)
        client_id = data['client_id']
        token = data['token']
        timestamp = data['timestamp']

        if client_id not in limits:
            print("DENY")
            continue

        if not QUOTA_SECRET:
            print("DENY")
            continue

        data = f"{client_id}{timestamp}".encode()
        expected_token = hashlib.sha256(data + QUOTA_SECRET.encode()).hexdigest()
        if token != expected_token:
            print("DENY")
            continue

        window = timestamp // 60
        if window_counts[window] >= limits[client_id]:
            print("DENY")
        else:
            window_counts[window] += 1
            print("ALLOW")

if __name__ == "__main__":
    if len(sys.argv) == 1:
        sys.exit(1)
    elif sys.argv[1] == "issue":
        issue()
    elif sys.argv[1] == "check":
        check()
    else:
        sys.exit(1)
